import SwiftUI
import UIKit

/// The pig-peek splash art, drawn from code (no PNG files).
/// Each layer is a 142 x 139 grid of 4 px squares on the same 568 x 556 canvas as the After Effects layers.
/// Digits: 0 = empty, 1 = outline, 2 = pig body, 3 = pig blush, 4 = fridge.
enum PigSplashArt {
    /// Colours come from the app palette (Assets.xcassets/Colors). Blush shades are the body mixed with Danger.
    struct Theme {
        let outline: UIColor   // ButtonDark #1F1A17
        let body: UIColor
        let blush: UIColor
        let fridge: UIColor
        let background: Color

        /// Yellow pig: BrandYellow body, blush = BrandYellow mixed 30 percent with Danger, ToggleGreen fridge.
        static let yellow = Theme(outline: hex(0x1F1A17), body: hex(0xFDF852), blush: hex(0xF2AE40),
                                  fridge: hex(0x1F7A4A), background: .white)
        /// White pig: Surface body, soft blush, BrandGreen fridge.
        static let white = Theme(outline: hex(0x1F1A17), body: hex(0xF2F4F5), blush: hex(0xEBB7BD),
                                 fridge: hex(0x00463C), background: .white)
        /// Light blush pig: DangerBackground body, ToggleGreen fridge.
        static let blush = Theme(outline: hex(0x1F1A17), body: hex(0xFFE5E5), blush: hex(0xF3A0A7),
                                 fridge: hex(0x1F7A4A), background: .white)
    }

    /// Change this one line to switch the splash colours.
    static let theme = Theme.yellow

    static let cell: CGFloat = 4
    static let canvas = CGSize(width: 568, height: 556)

    private static func hex(_ v: Int) -> UIColor {
        UIColor(red: CGFloat((v >> 16) & 0xFF) / 255, green: CGFloat((v >> 8) & 0xFF) / 255,
                blue: CGFloat(v & 0xFF) / 255, alpha: 1)
    }

    private static var cache: [String: UIImage] = [:]

    /// "fridge", "head" or "hand". Drawn once, then reused every frame.
    @MainActor
    static func image(_ layer: String) -> UIImage {
        if let hit = cache[layer] { return hit }
        let rows = layer == "fridge" ? fridge : layer == "head" ? head : hand
        let t = theme
        let colors: [Character: UIColor] = ["1": t.outline, "2": t.body, "3": t.blush, "4": t.fridge]
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = false
        let image = UIGraphicsImageRenderer(size: canvas, format: format).image { ctx in
            ctx.cgContext.interpolationQuality = .none
            ctx.cgContext.setShouldAntialias(false)
            for (y, row) in rows.enumerated() {
                let chars = Array(row)
                var x = 0
                while x < chars.count {
                    guard let color = colors[chars[x]] else { x += 1; continue }
                    var run = 1
                    while x + run < chars.count, chars[x + run] == chars[x] { run += 1 }
                    color.setFill()
                    ctx.fill(CGRect(x: CGFloat(x) * cell, y: CGFloat(y) * cell, width: CGFloat(run) * cell, height: cell))
                    x += run
                }
            }
        }
        cache[layer] = image
        return image
    }

